pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {airPort} from "../src/airPort.sol";

contract InvMutTest is Test {
    airPort c;
    function setUp() public { c = new airPort(); }
    function testRegression_property() public {
        address token = address(new RevertingToken());
        address from = address(0x123);
        address[] memory tos = new address[](1);
        tos[0] = address(0x456);
        uint256 v = 1;

        bool ok;
        try c.transfer(from, token, tos, v) {
            ok = true;
        } catch {
            ok = false;
        }

        assertTrue(!ok, "The call should revert due to require(_s) enforcing success");
    }
}

contract RevertingToken {
    fallback() external payable {
        revert("always revert");
    }
}
